#!/usr/bin/env bash
# Gate `one-home-paragraph` for [R:one-home-per-rule], generated by relearn from the rule file.
# Edit the rule, never this script: `relearn verify` reports a hand edit.
# Engine: duplicate-paragraph. Records: path, paragraph, tab-separated.
#   bash one-home-paragraph.sh <repository root>   0 clean, 1 finding, 2 could not check
#   bash one-home-paragraph.sh --judge < records   0 clean, 1 hit (the fixture runner)
# A `warn` gate prints its finding and exits 0.
set -uo pipefail
export LC_ALL=C

name='one-home-paragraph'
tag='R:one-home-per-rule'
message='The same paragraph is an original in two files, so a change to it must be made twice. Keep one, and make the other a reference to it or a generated copy. A generated copy is not a second home; relearn'\''s own emission paths are excluded for that reason.'
export RL_FILES='((^|/)([^/]+/)*[^/]*\.md$)'
export RL_EXCLUDE='((^|/)([^/]+/)*skills/([^/]+/)*SKILL\.md$)|((^|/)([^/]+/)*\.claude/rules/.*$)|((^|/)([^/]+/)*\.cursor/rules/.*$)|((^|/)([^/]+/)*\.github/copilot-instructions\.md$)|((^|/)([^/]+/)*AGENTS\.md$)'
export RL_MIN='160'

# Judge: 2 field(s) per record on stdin. 0 clean, 1 hit, 3 unreadable.
judge() {
  awk '
BEGIN {
  FS = "\t"
  files = ENVIRON["RL_FILES"]
  excl = ENVIRON["RL_EXCLUDE"]
  hits = 0
  bad = 0
  min = ENVIRON["RL_MIN"] + 0
}
$0 == "" { next }
NF != 2 { bad = 1; next }
$1 !~ files { next }
excl != "" && $1 ~ excl { next }
length($2) < min { next }
!($2 in first) { first[$2] = $1; next }
first[$2] != $1 && !(($2, $1) in seen) {
  seen[$2, $1] = 1
  shared[first[$2] " and " $1]++
  hits++
}
END {
  if (bad) exit 3
  for (pair in shared) print pair ": " shared[pair] " shared paragraph(s)" | "sort"
  close("sort")
  exit (hits > 0)
}
'
}

# Collect: every tracked file in scope, as paragraphs. A paragraph is a run
# of non-blank lines joined by one space, with CR removed and every run of
# whitespace made one space. A file `grep` reads as binary is skipped.
collect() {
  (
    cd "$1" || exit 1
    git ls-files -z | tr '\0' '\n' > "$work/paths.nl" || exit 1
    grep -E -- "$RL_FILES" "$work/paths.nl" > "$work/scoped" || true
    if [ -n "$RL_EXCLUDE" ]; then
      grep -vE -- "$RL_EXCLUDE" "$work/scoped" > "$work/kept" || true
    else
      cp "$work/scoped" "$work/kept"
    fi
    while IFS= read -r p; do
      [ -f "$p" ] || continue
      grep -qI '' "$p" || continue
      RL_PATH="$p" awk '
BEGIN { p = ENVIRON["RL_PATH"] }
{ gsub(/[ \t\r\f\v]+/, " "); sub(/^ /, ""); sub(/ $/, "") }
$0 == "" { if (para != "") print p "\t" para; para = ""; next }
{ para = (para == "") ? $0 : para " " $0 }
END { if (para != "") print p "\t" para }
' "$p"
    done < "$work/kept"
  )
}

if [ "${1:-}" = "--judge" ]; then
  judge
  exit $?
fi

disarmed() {
  printf '[%s] %s: DISARMED (exit 2, not a pass): %s\n' "$tag" "$name" "$1" >&2
  exit 2
}
root="${1:-.}"
command -v git >/dev/null 2>&1 || disarmed "git is not on PATH"
git -C "$root" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
  || disarmed "$root is not a git checkout"
work="$(mktemp -d)" || disarmed "no scratch directory"
trap 'rm -rf "$work"' EXIT
collect "$root" > "$work/records" || disarmed "the collect stage failed"
judge < "$work/records" > "$work/findings"
case $? in
  0) exit 0 ;;
  1) ;;
  *) disarmed "the judge could not read a record" ;;
esac
count="$(wc -l < "$work/findings" | tr -d ' ')"
printf '[%s] %s: WARNING. %s\n' "$tag" "$name" "$message"
printf '%s finding(s) in %s:\n' "$count" "$root"
sed 's/^/  /' "$work/findings"
exit 0

